import React, { useState } from 'react';
import { parseEventDate } from '../data/timeline';

const FL = { fontSize: 11, fontWeight: 500, color: 'var(--ink-3)', fontFamily: 'var(--font-mono)', letterSpacing: '0.05em', textTransform: 'uppercase', marginBottom: 5, fontStyle: 'normal', display: 'block' };
const Input = (props) => <input {...props} style={{ padding: '7px 10px', fontSize: 13, borderRadius: 6, width: '100%', border: '1px solid var(--paper-3)', background: 'var(--paper-2)', color: 'var(--ink)', ...props.style }} />;

export default function EventEditModal({ event, books, eventTypes, regions, onSave, onDelete, onClose, isNew, onManageTypes }) {
  // Migrate old single quote/note to bookNotes if needed
  const initialBookNotes = (() => {
    if (event.bookNotes?.length) return event.bookNotes;
    if ((event.bookIds?.length || event.bookId) && (event.quote || event.note)) {
      const bid = event.bookIds?.[0] || event.bookId;
      return [{ bookId: bid, quote: event.quote || '', note: event.note || '' }];
    }
    return (event.bookIds || []).map(bid => ({ bookId: bid, quote: '', note: '' }));
  })();

  const [draft, setDraft] = useState({
    ...event,
    bookIds: event.bookIds || (event.bookId ? [event.bookId] : []),
    bookNotes: initialBookNotes,
    tags: event.tags || [],
  });
  const [tagInput, setTagInput] = useState('');
  const [datePreview, setDatePreview] = useState(() => parseEventDate(event.dateRaw).display);

  const set = (k, v) => setDraft(d => ({ ...d, [k]: v }));

  const toggleBook = (id) => {
    const already = draft.bookIds.includes(id);
    const newBookIds = already ? draft.bookIds.filter(b => b !== id) : [...draft.bookIds, id];
    const newBookNotes = already
      ? draft.bookNotes.filter(bn => bn.bookId !== id)
      : [...draft.bookNotes, { bookId: id, quote: '', note: '' }];
    setDraft(d => ({ ...d, bookIds: newBookIds, bookNotes: newBookNotes }));
  };

  const updateBookNote = (bookId, field, value) => {
    setDraft(d => ({ ...d, bookNotes: d.bookNotes.map(bn => bn.bookId === bookId ? { ...bn, [field]: value } : bn) }));
  };

  const handleDateChange = (v) => { set('dateRaw', v); setDatePreview(parseEventDate(v).display); };
  const handleAddTag = (e) => {
    if ((e.key === 'Enter' || e.key === ',') && tagInput.trim()) {
      e.preventDefault();
      const tag = tagInput.trim().toLowerCase().replace(/,/g, '');
      if (!draft.tags.includes(tag)) set('tags', [...draft.tags, tag]);
      setTagInput('');
    }
  };
  const handleSubmit = (e) => {
    e.preventDefault();
    if (!draft.title.trim()) return;
    onSave({ ...draft, quote: undefined, note: undefined }); // remove legacy fields
    onClose();
  };

  const selectedBooks = books.filter(b => draft.bookIds.includes(b.id));

  return (
    <div onClick={e => e.target === e.currentTarget && onClose()}
      style={{ position: 'fixed', inset: 0, background: 'rgba(0,0,0,0.4)', display: 'flex', alignItems: 'center', justifyContent: 'center', zIndex: 200, padding: 20 }}>
      <div style={{ background: 'var(--paper-card)', borderRadius: 14, width: '100%', maxWidth: 620, maxHeight: '92vh', overflow: 'hidden', display: 'flex', flexDirection: 'column', boxShadow: 'var(--shadow-md)' }}>

        {/* Header */}
        <div style={{ padding: '15px 22px 11px', borderBottom: '1px solid var(--paper-3)', display: 'flex', justifyContent: 'space-between', alignItems: 'center', flexShrink: 0 }}>
          <span style={{ fontSize: 14, fontWeight: 500, color: 'var(--ink)' }}>{isNew ? 'Add timeline event' : 'Edit event'}</span>
          <div style={{ display: 'flex', gap: 8 }}>
            {!isNew && <button onClick={() => { if (window.confirm('Delete this event?')) { onDelete(event.id); onClose(); }}} style={{ fontSize: 12, padding: '4px 12px', borderRadius: 6, border: '1px solid var(--paper-3)', color: 'var(--red)', cursor: 'pointer' }}>Delete</button>}
            <button onClick={onClose} style={{ fontSize: 12, padding: '4px 12px', borderRadius: 6, border: '1px solid var(--paper-3)', color: 'var(--ink-3)', cursor: 'pointer' }}>Cancel</button>
          </div>
        </div>

        <form onSubmit={handleSubmit} style={{ flex: 1, overflowY: 'auto', padding: '16px 22px', display: 'flex', flexDirection: 'column', gap: 14 }}>

          {/* Title */}
          <div>
            <label style={FL}>Event title *</label>
            <Input autoFocus required value={draft.title} onChange={e => set('title', e.target.value)} placeholder="e.g. Battle of Marathon" />
          </div>

          {/* Date */}
          <div>
            <label style={FL}>Date</label>
            <div style={{ display: 'flex', gap: 8, alignItems: 'center' }}>
              <Input value={draft.dateRaw || ''} onChange={e => handleDateChange(e.target.value)} placeholder='e.g. 490 BCE · March 1453 · 1492' style={{ flex: 1 }} />
              {datePreview && <div style={{ fontSize: 12, color: 'var(--accent)', background: 'var(--accent-light)', padding: '5px 10px', borderRadius: 6, whiteSpace: 'nowrap', fontStyle: 'italic' }}>→ {datePreview}</div>}
            </div>
          </div>

          {/* Region + Type */}
          <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 12 }}>
            <div>
              <label style={FL}>Region</label>
              <select value={draft.region || ''} onChange={e => set('region', e.target.value)}
                style={{ width: '100%', padding: '7px 28px 7px 10px', fontSize: 13, borderRadius: 6, border: '1px solid var(--paper-3)', background: 'var(--paper-2)', color: 'var(--ink)' }}>
                <option value="">Select…</option>
                {regions.map(r => <option key={r.id} value={r.id}>{r.label}</option>)}
              </select>
            </div>
            <div>
              <label style={{ ...FL, display: 'flex', alignItems: 'center', gap: 8 }}>
                Event type
                <button type="button" onClick={onManageTypes} style={{ fontSize: 10, color: 'var(--ink-4)', textDecoration: 'underline', cursor: 'pointer', background: 'none', border: 'none', fontFamily: 'var(--font-mono)', fontStyle: 'normal', fontWeight: 400, textTransform: 'none', letterSpacing: 0 }}>manage</button>
              </label>
              <select value={draft.type || ''} onChange={e => set('type', e.target.value)}
                style={{ width: '100%', padding: '7px 28px 7px 10px', fontSize: 13, borderRadius: 6, border: '1px solid var(--paper-3)', background: 'var(--paper-2)', color: 'var(--ink)' }}>
                <option value="">Select…</option>
                {eventTypes.map(t => <option key={t.id} value={t.id}>{t.label}</option>)}
              </select>
            </div>
          </div>

          {/* Book selector */}
          <div>
            <label style={FL}>Books that discuss this event</label>
            <div style={{ display: 'flex', flexWrap: 'wrap', gap: 6 }}>
              {books.map(b => {
                const sel = draft.bookIds.includes(b.id);
                return (
                  <button key={b.id} type="button" onClick={() => toggleBook(b.id)}
                    style={{ fontSize: 11, padding: '4px 11px', borderRadius: 20, cursor: 'pointer', display: 'flex', alignItems: 'center', gap: 5, border: `1px solid ${sel ? b.color : 'var(--paper-3)'}`, background: sel ? b.color + '22' : 'transparent', color: sel ? b.color : 'var(--ink-3)', fontWeight: sel ? 500 : 400 }}>
                    <div style={{ width: 6, height: 6, borderRadius: '50%', background: sel ? b.color : 'var(--paper-3)' }} />
                    {b.title}
                  </button>
                );
              })}
            </div>
          </div>

          {/* Per-book quote + note */}
          {selectedBooks.length > 0 && (
            <div>
              <label style={FL}>Quotes & notes per book</label>
              {selectedBooks.map(book => {
                const bn = draft.bookNotes.find(n => n.bookId === book.id) || { bookId: book.id, quote: '', note: '' };
                return (
                  <div key={book.id} style={{ background: 'var(--paper-2)', border: `1px solid ${book.color}33`, borderLeft: `3px solid ${book.color}`, borderRadius: 8, padding: '10px 12px', marginBottom: 10 }}>
                    <div style={{ display: 'flex', alignItems: 'center', gap: 6, marginBottom: 8 }}>
                      <div style={{ width: 7, height: 7, borderRadius: '50%', background: book.color }} />
                      <span style={{ fontSize: 11, fontWeight: 500, color: book.color, fontStyle: 'italic' }}>{book.title}</span>
                    </div>
                    <textarea value={bn.quote} onChange={e => updateBookNote(book.id, 'quote', e.target.value)}
                      placeholder="Quote from this book…"
                      rows={2}
                      style={{ width: '100%', resize: 'vertical', padding: '6px 8px', fontSize: 12, borderRadius: 5, fontStyle: 'italic', color: 'var(--ink-2)', background: 'var(--paper-card)', border: '1px solid var(--paper-3)', fontFamily: 'var(--font-serif)', marginBottom: 6 }} />
                    <textarea value={bn.note} onChange={e => updateBookNote(book.id, 'note', e.target.value)}
                      placeholder="Your note on how this author discusses the event…"
                      rows={2}
                      style={{ width: '100%', resize: 'vertical', padding: '6px 8px', fontSize: 12, borderRadius: 5, color: 'var(--ink)', background: 'var(--paper-card)', border: '1px solid var(--paper-3)', fontFamily: 'var(--font-serif)' }} />
                  </div>
                );
              })}
            </div>
          )}

          {/* Tags */}
          <div>
            <label style={FL}>Tags</label>
            <div style={{ border: '1px solid var(--paper-3)', borderRadius: 6, padding: '5px 8px', display: 'flex', flexWrap: 'wrap', gap: 5, alignItems: 'center', background: 'var(--paper-2)' }}>
              {draft.tags.map(tag => (
                <span key={tag} style={{ fontSize: 11, padding: '2px 8px', borderRadius: 20, background: 'var(--accent-light)', color: 'var(--accent)', display: 'flex', alignItems: 'center', gap: 4 }}>
                  #{tag}
                  <button type="button" onClick={() => set('tags', draft.tags.filter(t => t !== tag))} style={{ fontSize: 10, cursor: 'pointer', background: 'none', border: 'none', color: 'var(--accent)', padding: 0 }}>✕</button>
                </span>
              ))}
              <input value={tagInput} onChange={e => setTagInput(e.target.value)} onKeyDown={handleAddTag}
                placeholder={draft.tags.length ? '' : 'e.g. trade, empire… (Enter to add)'}
                style={{ border: 'none', outline: 'none', fontSize: 12, background: 'transparent', minWidth: 100, color: 'var(--ink)', fontFamily: 'var(--font-serif)' }} />
            </div>
          </div>
        </form>

        <div style={{ padding: '12px 22px', borderTop: '1px solid var(--paper-3)', display: 'flex', justifyContent: 'flex-end', flexShrink: 0 }}>
          <button onClick={handleSubmit} style={{ fontSize: 13, padding: '8px 24px', borderRadius: 7, background: 'var(--accent)', color: 'var(--paper-card)', border: 'none', cursor: 'pointer' }}>
            {isNew ? 'Add event' : 'Save changes'}
          </button>
        </div>
      </div>
    </div>
  );
}
